package cn.zhuatech.visionai.controller; import cn.zhuatech.visionai.common.ApiResponse; import cn.zhuatech.visionai.dto.VisionAiDto.*; import cn.zhuatech.visionai.service.VisionAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final VisionAiService service;public OperationsAdminController(VisionAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
